create table public.playground_simulations (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, base_version_id uuid not null references public.architecture_versions(id), name text not null, description text, status text not null default 'draft' check (status in ('draft', 'simulating', 'completed', 'applied', 'discarded', 'failed')), proposed_changes jsonb not null default '[]'::jsonb, before_architecture jsonb not null default '{}'::jsonb, after_architecture jsonb not null default '{}'::jsonb, metrics jsonb not null default '{}'::jsonb, impact_analysis jsonb not null default '{}'::jsonb, ai_analysis jsonb not null default '{}'::jsonb, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.documentation_documents (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, type text not null, title text not null, content text not null, format text not null check (format in ('markdown', 'html', 'mermaid')), source_version_id uuid references public.architecture_versions(id), generated_by uuid not null references auth.users(id), status text not null default 'up_to_date' check (status in ('up_to_date', 'outdated')), manually_edited boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.project_stories (id uuid primary key default gen_random_uuid(), project_id uuid not null unique references public.projects(id) on delete cascade, content jsonb not null default '{}'::jsonb, generated_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.ai_runs (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, user_id uuid not null references auth.users(id), operation text not null, provider text not null, model text, status text not null check (status in ('queued', 'running', 'completed', 'failed')), input_metadata jsonb not null default '{}'::jsonb, output_metadata jsonb not null default '{}'::jsonb, token_usage jsonb not null default '{}'::jsonb, latency_ms integer, error text, created_at timestamptz not null default now(), completed_at timestamptz);
create index playground_project_idx on public.playground_simulations(project_id, created_at desc); create index documentation_project_idx on public.documentation_documents(project_id, updated_at desc); create index ai_runs_project_idx on public.ai_runs(project_id, created_at desc);
create trigger playground_updated_at before update on public.playground_simulations for each row execute function public.set_updated_at(); create trigger documentation_updated_at before update on public.documentation_documents for each row execute function public.set_updated_at(); create trigger stories_updated_at before update on public.project_stories for each row execute function public.set_updated_at();
alter table public.playground_simulations enable row level security; alter table public.documentation_documents enable row level security; alter table public.project_stories enable row level security; alter table public.ai_runs enable row level security;
create policy playground_access on public.playground_simulations for select using (public.is_workspace_member((select workspace_id from public.projects where id = project_id))); create policy playground_manage on public.playground_simulations for all using (public.is_workspace_member((select workspace_id from public.projects where id = project_id))) with check (public.is_workspace_member((select workspace_id from public.projects where id = project_id)));
create policy documentation_access on public.documentation_documents for select using (public.is_workspace_member((select workspace_id from public.projects where id = project_id))); create policy documentation_manage on public.documentation_documents for all using (public.is_workspace_member((select workspace_id from public.projects where id = project_id))) with check (public.is_workspace_member((select workspace_id from public.projects where id = project_id)));
create policy stories_access on public.project_stories for select using (public.is_workspace_member((select workspace_id from public.projects where id = project_id))); create policy stories_manage on public.project_stories for all using (public.is_workspace_member((select workspace_id from public.projects where id = project_id))) with check (public.is_workspace_member((select workspace_id from public.projects where id = project_id)));
create policy ai_runs_access on public.ai_runs for select using (public.is_workspace_member((select workspace_id from public.projects where id = project_id))); create policy ai_runs_insert on public.ai_runs for insert with check (user_id = auth.uid() and public.is_workspace_member((select workspace_id from public.projects where id = project_id)));
alter publication supabase_realtime add table public.playground_simulations, public.ai_runs;